// 🧭 Định tuyến: menu, nút bấm, ảnh, lệnh gõ tay. Ghi nhớ chế độ theo từng người dùng.
const sd = $getWorkflowStaticData('global');
const upd = $json;
const key = (id) => 'mode_' + id;
let out = { route: 'MENU' };

if (upd.callback_query) {
  const cq = upd.callback_query;
  const data = cq.data || '';
  const chatId = (cq.message && cq.message.chat && cq.message.chat.id) || (cq.from && cq.from.id);
  out.chatId = chatId;
  if (data === 'mode_cccd') { sd[key(chatId)] = 'cccd'; out.route='MODE_SET'; out.modeText='🪪 Đã bật chế độ CCCD.\nHãy GỬI ẢNH căn cước công dân (mặt trước, hoặc cả 2 mặt) ngay bây giờ.'; }
  else if (data === 'mode_can') { sd[key(chatId)] = 'can'; out.route='MODE_SET'; out.modeText='⚖️ Đã bật chế độ Phiếu cân.\nHãy GỬI ẢNH phiếu cân ngay bây giờ.'; }
  else if (data === 'help_mua') { out.route='MODE_SET'; out.modeText='🌾 Ghi mua lúa — gõ theo mẫu (ngăn bằng dấu |):\nmua | Tên người bán | Loại lúa | Số kg | Đơn giá\n\nVí dụ:\nmua | Diệp Thành Hòa | OM5451 | 5200 | 8200\n\n🔎 Tra người bán đã lưu: gõ  ai Tên  hoặc  ai Số_CCCD'; }
  else if (data === 'act_baocao') { out.route='BAOCAO'; }
  else { out.route='MENU'; }
}
else if (upd.message) {
  const msg = upd.message;
  const chatId = (msg.chat && msg.chat.id) || (msg.from && msg.from.id);
  out.chatId = chatId;
  out.messageId = msg.message_id || '';
  const t = (msg.text || '').trim();
  const low = t.toLowerCase();
  const has = (s) => t.indexOf(s) !== -1;
  const hasPhoto = Array.isArray(msg.photo) && msg.photo.length > 0;
  const doc = msg.document;
  const isImg = doc && (doc.mime_type || '').indexOf('image/') === 0;
  const muaHelp = '🌾 Ghi mua lúa — gõ theo mẫu (ngăn bằng dấu |):\nmua | Tên người bán | Loại lúa | Số kg | Đơn giá\n\nVí dụ:\nmua | Diệp Thành Hòa | OM5451 | 5200 | 8200\n\n🔎 Tra người bán đã lưu: gõ  ai Tên  hoặc  ai Số_CCCD';

  if (/^\/?start\b/i.test(t) || has('🏠') || low === 'menu') out.route='MENU';
  else if (has('🪪') || /^(cccd|căn cước|can cuoc)\b/i.test(low)) { sd[key(chatId)]='cccd'; out.route='MODE_SET'; out.modeText='🪪 Đã bật chế độ CCCD. Gửi ẢNH căn cước ngay bây giờ.'; }
  else if (has('⚖️') || /^(phiếu cân|phieu can|cân|can)\b/i.test(low)) { sd[key(chatId)]='can'; out.route='MODE_SET'; out.modeText='⚖️ Đã bật chế độ Phiếu cân. Gửi ẢNH phiếu cân ngay bây giờ.'; }
  else if (/^mua\b/i.test(low) && has('|')) { out.route='MUA'; out.text=t; }
  else if (has('🌾') || /^mua\b/i.test(low)) { out.route='MODE_SET'; out.modeText=muaHelp; }
  else if (has('📊') || /^(bc|báo cáo|bao cao)\b/i.test(low)) out.route='BAOCAO';
  else if (/^ai\b/i.test(low)) { out.route='TRA'; out.text=t; }
  else if (hasPhoto || isImg) {
    out.fileId = hasPhoto ? msg.photo[msg.photo.length-1].file_id : doc.file_id;
    const mode = sd[key(chatId)] || 'can';
    out.mode = mode;
    out.route = (mode === 'cccd') ? 'CCCD' : 'CAN';
  }
  else out.route='MENU';
}
return { json: out };

