  "kieu_can": "NHẬP hay XUẤT",
  "ghi_chu_chat_luong": "tạp chất/đơn giá/thành tiền",
  "nguoi_can": "người cân",
  "do_tin_cay": "cao | trung bình | thấp",
  "can_kiem_tra": true hoặc false,
  "ly_do_kiem_tra": "lý do"
}
Trường không có để rỗng. Số cân chỉ ghi con số, không kèm 'kg', không dấu phẩy nghìn.";
return { json: {
  chatId: r.chatId,
  messageId: r.messageId || '',
  fileName: bin.fileName || ('phieucan_' + (r.messageId || '') + '.jpg'),
  body: { contents: [{ parts: [ { text: prompt }, { inline_data: { mime_type: mimeType, data: base64 } } ] }], generationConfig: { temperature: 0, response_mime_type: 'application/json' } }
} };

// JSON Gemini -> cột PHIEU_CAN + kiểm tra số cân
const prep = $('Chuẩn bị cân').item.json;
const fileName = prep.fileName;
let text=''; try{ text=$json.candidates[0].content.parts[0].text; }catch(e){ text=''; }
let clean=(text||'').trim().replace(/^```json/i,'').replace(/^```/,'').replace(/```$/,'').trim();
let data={}; let parseError='';
try{ data=JSON.parse(clean); }catch(e){ parseError='Không đọc được JSON từ AI'; }
const toNum=(s)=>{ if(s===null||s===undefined||s==='')return null; const n=Number(String(s).replace(/[^0-9.\-]/g,'')); return isNaN(n)?null:n; };
const vao=toNum(data.tl_xe_vao), ra=toNum(data.tl_xe_ra); let hang=toNum(data.tl_hang);
if(hang===null && vao!==null && ra!==null) hang=Math.abs(vao-ra);
let mathOk=true, mathNote='';
if(vao!==null && ra!==null && hang!==null){ const diff=Math.abs(Math.abs(vao-ra)-hang); if(diff>Math.max(20,hang*0.01)){ mathOk=false; mathNote='Lệch cân: |'+vao+'-'+ra+'| khác '+hang; } }
const conf=String(data.do_tin_cay||'').toLowerCase();
const lowConf=conf.includes('thấp')||conf.includes('thap')||conf==='low';
const aiFlag=data.can_kiem_tra===true||data.can_kiem_tra==='true';
const needs=!!(parseError||lowConf||!mathOk||aiFlag);
const reasons=[]; if(parseError)reasons.push(parseError); if(lowConf)reasons.push('AI báo độ tin cậy thấp'); if(!mathOk)reasons.push(mathNote); if(aiFlag&&data.ly_do_kiem_tra)reasons.push(data.ly_do_kiem_tra); else if(aiFlag)reasons.push('AI đánh dấu cần kiểm tra');
return { json: {
  'Thời gian xử lý': new Date().toISOString(),
  'Tên file': fileName||'',
  'Link ảnh': prep.messageId ? ('telegram-msg-'+prep.messageId) : '',
  'Ngày phiếu': data.ngay||'',
  'Số phiếu': data.so_phieu||'',
  'Người bán / Khách hàng': data.nguoi_ban_khach_hang||'',
  'Loại hàng / lúa': data.loai_hang_lua||'',
  'Số xe': data.so_xe||'',
  'TL xe vào (kg)': vao!==null?vao:'',
  'TL xe ra (kg)': ra!==null?ra:'',
  'TL hàng (kg)': hang!==null?hang:'',
  'Độ ẩm (%)': data.do_am||'',
  'Kiểu cân': data.kieu_can||'',
  'Ghi chú chất lượng': data.ghi_chu_chat_luong||'',
  'Người cân': data.nguoi_can||'',
  'Độ tin cậy': data.do_tin_cay||'',
  'Cần kiểm tra': needs?'CÓ':'Không',
  'Lý do kiểm tra': reasons.join('; ')
} };

