// Phân tích lệnh mua lúa
const r = $('Định tuyến').item.json;
const raw = (r.text || '');
let p = raw.replace(/^mua\s*[:|]?\s*/i,'').split('|').map(s=>s.trim());
const ten=p[0]||'', loai=p[1]||'', kg=p[2]||'', gia=p[3]||'';
const kgN=Number(String(kg).replace(/[^0-9.]/g,''))||0;
const giaN=Number(String(gia).replace(/[^0-9.]/g,''))||0;
return { json: { chatId:r.chatId, ten, loai, kg:kgN, gia:giaN, thanhtien:kgN*giaN } };

// Ghép thông tin người bán từ CCCD_DATA (nếu có)
const rows = $input.all().map(i=>i.json);
const mua = $('Phân tích mua').first().json;
const norm = s => (s||'').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/\s+/g,' ').trim();
const key = norm(mua.ten);
const digits = (mua.ten||'').replace(/\D/g,'');
let m=null;
for(const row of rows){
  const name=norm(row['Họ và tên']); const cccd=(row['Số CCCD']||'').toString();
  if(digits && digits.length>=9 && cccd===digits){ m=row; break; }
  if(key && name && (name.includes(key)||key.includes(name))){ m=row; break; }
}
return { json: {
  'Thời gian': new Date().toISOString(),
  'Người bán': (m&&m['Họ và tên'])||mua.ten,
  'Số CCCD': (m&&m['Số CCCD'])||'',
  'Địa chỉ (thường trú)': (m&&m['Nơi thường trú'])||'',
  'Loại lúa': mua.loai,
  'Số kg': mua.kg,
  'Đơn giá': mua.gia,
  'Thành tiền': mua.thanhtien
} };

const r=$('Định tuyến').item.json;
const q=(r.text||'').replace(/^ai\s*/i,'').trim();
return { json: { chatId:r.chatId, q } };

// Tra người bán trong CCCD_DATA
const rows=$input.all().map(i=>i.json);
const q=$('Tìm người bán').first().json.q;
const chatId=$('Tìm người bán').first().json.chatId;
const norm=s=>(s||'').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/\s+/g,' ').trim();
const key=norm(q); const digits=(q||'').replace(/\D/g,'');
const hits=[];
for(const row of rows){ const name=norm(row['Họ và tên']); const cccd=(row['Số CCCD']||'').toString();
  if((digits && digits.length>=9 && cccd.includes(digits)) || (key && name && name.includes(key))) hits.push(row); }
let text;
if(!q) text='Gõ:  ai Tên  hoặc  ai Số_CCCD  để tra người bán.';
else if(!hits.length) text='🔎 Không tìm thấy người bán khớp "'+q+'" trong danh bạ CCCD.';
else { text='🔎 Tìm thấy '+hits.length+' người bán:\n\n'+hits.slice(0,5).map(h=>('👤 '+(h['Họ và tên']||'')+'\n• CCCD: '+(h['Số CCCD']||'-')+'\n• Ngày sinh: '+(h['Ngày sinh']||'-')+'\n• Địa chỉ: '+(h['Nơi thường trú']||'-'))).join('\n\n'); }
return { json: { chatId, text } };

// Đếm phiếu cân hôm nay
const rows=$input.all().map(i=>i.json);
const chatId=$('Định tuyến').first().json.chatId;
const now=new Date(); const y=now.getFullYear(), mo=now.getMonth(), d=now.getDate();
let soPhieu=0, tongKg=0, canKt=0;
for(const row of rows){ const t=row['Thời gian xử lý']; if(!t)continue; const dt=new Date(t); if(isNaN(dt))continue;
  if(dt.getFullYear()===y && dt.getMonth()===mo && dt.getDate()===d){ soPhieu++; const kg=Number(String(row['TL hàng (kg)']||'').replace(/[^0-9.]/g,''))||0; tongKg+=kg; if(String(row['Cần kiểm tra']).toUpperCase()==='CÓ')canKt++; } }
const text='📊 BÁO CÁO HÔM NAY ('+d+'/'+(mo+1)+'/'+y+')\n\n⚖️ Phiếu cân: '+soPhieu+' phiếu\n📦 Tổng khối lượng hàng: '+tongKg.toLocaleString('vi-VN')+' kg\n⚠️ Cần kiểm tra: '+canKt+' phiếu'+(canKt?' (mở Sheet lọc cột "Cần kiểm tra"=CÓ)':'');
return { json: { chatId, text } };
